import{FIELD,DEFAULT_FEEL_TUNING,createFootball2DState,stepFootball2D}from"./football2dModel.js";import{createOpponentState,stepOpponentAI}from"./opponentAI.js";import{stepGoalkeeper}from"./goalkeeperAI.js";import{DEFAULT_ATHLETIC_PROFILE,getAthleticMotion}from"./playerAthleticProfile.js";
const TURN_RATE=5.5,PROTECT_TURN_RATE=3.6,clamp=(v,min,max)=>Math.min(max,Math.max(min,v));function wrapAngle(a){while(a>Math.PI)a-=Math.PI*2;while(a<-Math.PI)a+=Math.PI*2;return a}function moveToward(a,b,d){return a<b?Math.min(b,a+d):Math.max(b,a-d)}function steerInput(state,input,dt,magnitude,protecting){const x=input.moveX??0,y=input.moveY??0,current=state.steerAngle??Math.atan2(state.player.facingY,state.player.facingX);if(Math.hypot(x,y)<.01)return{input:{...input,moveX:0,moveY:0},angle:current};const desired=Math.atan2(y,x),rate=protecting?PROTECT_TURN_RATE:TURN_RATE,delta=wrapAngle(desired-current),next=current+clamp(delta,-rate*dt,rate*dt);return{input:{...input,moveX:Math.cos(next)*magnitude,moveY:Math.sin(next)*magnitude},angle:next}}
function shieldDirection(player,defender){const x=player.x-defender.x,y=player.y-defender.y,l=Math.hypot(x,y)||1;return{x:x/l,y:y/l}}
export function createScenarioState(){return{...createFootball2DState(),...createOpponentState(FIELD),steerAngle:0,driveMagnitude:0,burstTime:0}}
export function stepScenario(s,i={},dt=1/60,tuning=DEFAULT_FEEL_TUNING,athletic=DEFAULT_ATHLETIC_PROFILE){const motion=getAthleticMotion(athletic),total=Math.min(Math.max(dt,0),.05),count=Math.max(1,Math.ceil(total/(1/90))),slice=total/count;let n={...s};for(let x=0;x<count;x++){const first=x===0,protecting=!!i.protecting&&n.possession;if(first&&i.burstTriggered&&n.possession&&!protecting)n={...n,burstTime:motion.burstDuration};const burst=n.burstTime>0,raw=clamp(Math.hypot(i.moveX??0,i.moveY??0),0,1),target=protecting?Math.min(raw,.48):raw,rate=(target>n.driveMagnitude?motion.accelerationPerSecond*(burst?motion.burstAccelerationScale:1):motion.decelerationPerSecond),drive=moveToward(n.driveMagnitude,target,rate*slice),shield=shieldDirection(n.player,n.defender),before={...n.ball},steer=steerInput(n,first?i:{...i,shootReleased:false,burstTriggered:false},slice,drive,protecting),maxSpeedScale=motion.maxSpeedScale*(burst?motion.burstMaxScale:1);const modelInput={...steer.input,protecting,shieldX:shield.x,shieldY:shield.y,burstActive:burst,burstTriggered:first&&!!i.burstTriggered,maxSpeedScale};n={...stepFootball2D(n,modelInput,slice,tuning),steerAngle:steer.angle,driveMagnitude:drive,burstTime:Math.max(0,n.burstTime-slice)};if(n.status==="goal")break;const d=stepOpponentAI({defender:n.defender,keeper:n.keeper,player:n.player,ball:n.ball,possession:n.possession,protecting},FIELD,slice);n={...n,defender:d.defender,keeper:d.keeper,ball:d.ball,possession:d.possession,lastEvent:d.event??n.lastEvent};const k=stepGoalkeeper(n.keeper,before,n.ball,FIELD,slice);n={...n,keeper:k.keeper,ball:k.ball,possession:k.event?false:n.possession,lastEvent:k.event??n.lastEvent}}return n}
